<template>
  <div class="enterprise">
    <header class="hero">
      <div><span>ENTERPRISE CONTROL CENTER</span><h1>企业控制台</h1><p>统一管理团队、权限、知识资产、自动化、开放集成、配额和运行状态。</p></div>
      <aside><small>当前组织</small><select v-model="activeOrganization" @change="switchOrganization"><option v-for="item in organizations" :key="item.id" :value="item.id">{{ item.name }}</option></select><em>{{ roleNames[data.organization?.role] }}</em></aside>
    </header>
    <section class="metrics"><article v-for="item in metrics" :key="item.name"><i>{{ item.icon }}</i><div><b>{{ item.value }}</b><small>{{ item.name }}</small></div></article></section>
    <nav class="tabs"><button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" @click="selectTab(item.key)">{{ item.name }}</button></nav>

    <section v-if="loading" class="panel empty">正在加载企业数据...</section>
    <section v-else-if="tab==='team'" class="panel">
      <PanelTitle title="组织与成员" text="角色按照访客、成员、复核员、管理员、所有者逐级授权。"><button class="primary" @click="open('member')">添加成员</button></PanelTitle>
      <div class="rows"><div v-for="member in organization.members" :key="member.id" class="member"><i>{{ member.username[0] }}</i><div><b>{{ member.username }}</b><small>{{ member.email }}</small></div><select v-model="member.role" :disabled="member.role==='owner'" @change="saveRole(member)"><option v-for="role in roles" :key="role.value" :value="role.value">{{ role.name }}</option></select><span>{{ member.status==='active'?'正常':'已移除' }}</span><button v-if="member.role!=='owner'" class="danger" @click="dropMember(member)">移除</button></div></div>
    </section>
    <section v-else-if="tab==='audit'" class="panel">
      <PanelTitle title="审计日志" text="关键操作记录操作者、业务资源、时间与变更摘要。"><button class="link" @click="loadAudit">刷新</button></PanelTitle>
      <div class="rows"><div v-for="item in audits" :key="item.id" class="audit"><i>记</i><div><b>{{ actionName(item.action) }}</b><small>{{ item.resource_type }} · {{ short(item.resource_id) }} · {{ date(item.created_at) }}</small></div><code>{{ detail(item.detail) }}</code></div><p v-if="!audits.length" class="empty">暂无审计记录</p></div>
    </section>
    <section v-else-if="tab==='knowledge'" class="panel">
      <PanelTitle title="企业知识库" text="将文档资产组织为可检索知识集合，为 RAG 提供真实来源。"><div><RouterLink class="link" to="/workspace/knowledge">进入证据中心</RouterLink><button class="primary" @click="open('knowledge')">新建知识库</button></div></PanelTitle>
      <div class="cards"><article v-for="item in knowledge" :key="item.id"><span>知识集合</span><h3>{{ item.name }}</h3><p>{{ item.description || '暂无说明' }}</p><b>{{ item.documents }} 份文档 · {{ modeNames[item.retrieval_mode] }}</b><small>{{ date(item.updated_at) }}</small></article><p v-if="!knowledge.length" class="empty">暂无知识库</p></div>
    </section>
    <section v-else-if="tab==='automation'" class="panel">
      <PanelTitle title="计划任务与失败补偿" text="使用 Cron 调度已发布工作流，并配置失败重试上限。"><button class="primary" @click="open('schedule')">新建计划</button></PanelTitle>
      <div class="rows"><div v-for="item in schedules" :key="item.id" class="schedule"><div><b>{{ item.name }}</b><small>{{ short(item.workflow_id) }}</small></div><code>{{ item.cron_expression }}</code><span>{{ item.timezone }}</span><span>重试 {{ item.retry_limit }} 次</span><em>{{ item.status==='active'?'运行中':'已暂停' }}</em><button class="danger" @click="dropSchedule(item)">删除</button></div><p v-if="!schedules.length" class="empty">暂无计划任务</p></div>
    </section>
    <div v-else-if="tab==='integration'" class="columns">
      <section class="panel"><PanelTitle title="开放 API" text="密钥仅创建时显示，服务端只保存摘要。"><button class="primary" @click="open('key')">创建密钥</button></PanelTitle><ItemList :items="apiKeys" empty="暂无 API 密钥"><template #default="{item}"><div><b>{{ item.name }}</b><small>{{ item.prefix }}•••• · {{ item.scopes.join(', ') }}</small></div><span>{{ item.revoked?'已撤销':'有效' }}</span><button v-if="!item.revoked" class="danger" @click="dropKey(item)">撤销</button></template></ItemList></section>
      <section class="panel"><PanelTitle title="Webhook" text="事件订阅使用独立签名密钥，并保留每次投递结果。"><button class="primary" @click="open('webhook')">添加端点</button></PanelTitle><ItemList :items="webhooks" empty="暂无 Webhook"><template #default="{item}"><div><b>{{ item.name }}</b><small>{{ item.url }}</small></div><span>{{ item.events.length }} 个事件</span><button class="link" @click="tryWebhook(item)">测试</button><button class="danger" @click="dropWebhook(item)">删除</button></template></ItemList><h3 class="sub-title">最近投递</h3><div class="delivery-list"><div v-for="item in deliveries.slice(0,6)" :key="item.id"><i :class="item.status"></i><span><b>{{ item.event }}</b><small>{{ date(item.created_at) }} · HTTP {{ item.response_status || '—' }}</small></span><em>{{ deliveryNames[item.status] || item.status }}</em></div><p v-if="!deliveries.length" class="empty compact">暂无投递记录</p></div></section>
    </div>
    <div v-else-if="tab==='operations'" class="columns">
      <section class="panel"><PanelTitle title="运行状态" text="服务健康度、任务队列和最近失败。"><button class="link" @click="loadOperations">刷新</button></PanelTitle><div class="services"><div v-for="(state,name) in operations.services" :key="name"><i :class="{bad:state.status==='unavailable'||state.status==='unconfigured'}"></i><b>{{ serviceNames[name]||name }}</b><small>{{ serviceState(state) }}</small></div></div><div class="task-counts"><span v-for="(count,state) in operations.task_counts" :key="state"><b>{{ count }}</b>{{ state }}</span></div></section>
      <section class="panel"><PanelTitle title="备份与恢复准备" text="归档组织清单与原始文档，数据库由 PostgreSQL 灾备负责。"><button class="primary" :disabled="backing" @click="backup">{{ backing?'备份中...':'立即备份' }}</button></PanelTitle><ItemList :items="backups" empty="暂无备份记录"><template #default="{item}"><div><b>{{ bytes(item.size_bytes) }}</b><small>{{ date(item.created_at) }} · {{ item.checksum.slice(0,12) }}</small></div><span>已完成</span></template></ItemList></section>
    </div>
    <section v-else class="panel">
      <PanelTitle title="套餐、配额与用量" text="本地部署采用手动套餐适配器，不伪造在线支付结果。" />
      <div class="plans"><article v-for="plan in plans" :key="plan.key" :class="{current:data.subscription?.plan===plan.key}"><span>{{ plan.name }}</span><h3>{{ plan.price }}</h3><p v-for="line in plan.lines" :key="line">✓ {{ line }}</p><button :disabled="data.subscription?.plan===plan.key" @click="setPlan(plan.key)">{{ data.subscription?.plan===plan.key?'当前套餐':'切换套餐' }}</button></article></div>
      <div class="usage"><div v-for="item in usage" :key="item.name"><span><b>{{ item.name }}</b><small>{{ item.used }} / {{ item.limit }}</small></span><i><em :style="{width:item.percent+'%'}"></em></i></div></div>
    </section>

    <div v-if="dialog" class="mask" @click.self="dialog=''">
      <form class="modal" @submit.prevent="submit"><header><div><h2>{{ dialogTitle }}</h2><p>配置会立即写入当前组织。</p></div><button type="button" @click="dialog=''">×</button></header>
        <template v-if="dialog==='member'"><label>注册邮箱<input v-model.trim="form.email" type="email" required></label><label>角色<select v-model="form.role"><option v-for="role in roles.filter(r=>r.value!=='owner')" :key="role.value" :value="role.value">{{ role.name }}</option></select></label></template>
        <template v-if="dialog==='knowledge'"><label>名称<input v-model.trim="form.name" required></label><label>说明<textarea v-model.trim="form.description"></textarea></label><label>检索模式<select v-model="form.retrieval_mode"><option value="hybrid">混合检索</option><option value="keyword">关键词检索</option><option value="vector">向量检索</option></select></label></template>
        <template v-if="dialog==='schedule'"><label>计划名称<input v-model.trim="form.name" required></label><label>工作流<select v-model="form.workflow_id" required><option value="" disabled>请选择</option><option v-for="item in workflows" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>处理文档<select v-model="form.document_id" required><option value="" disabled>请选择</option><option v-for="item in documents" :key="item.id" :value="item.id">{{ item.filename }}</option></select></label><label>Cron<input v-model.trim="form.cron_expression" required></label><label>重试次数<input v-model.number="form.retry_limit" type="number" min="0" max="10"></label></template>
        <template v-if="dialog==='key'"><label>密钥名称<input v-model.trim="form.name" required></label><label>权限范围<select v-model="form.scope"><option value="workspace:read">工作台只读</option><option value="workspace:write">工作台读写</option><option value="enterprise:read">企业只读</option><option value="*">全部权限</option></select></label></template>
        <template v-if="dialog==='webhook'"><label>端点名称<input v-model.trim="form.name" required></label><label>HTTPS 地址<input v-model.trim="form.url" type="url" required></label><label>事件<input v-model.trim="form.events"></label></template>
        <footer><button type="button" class="secondary" @click="dialog=''">取消</button><button class="primary" :disabled="saving">{{ saving?'保存中...':'保存' }}</button></footer>
      </form>
    </div>
    <div v-if="secret" class="secret"><b>请立即保存，仅显示一次</b><code>{{ secret }}</code><button @click="copy">复制</button><button @click="secret=''">关闭</button></div>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref } from 'vue'
import { getDocuments, getWorkflows } from '../../api/workspace'
import { activateOrganization, addMember, changePlan, createApiKey, createBackup, createKnowledge, createSchedule, createWebhook, deleteSchedule, deleteWebhook, getApiKeys, getAuditLogs, getBackups, getEnterpriseDashboard, getKnowledge, getOperations, getOrganization, getOrganizations, getSchedules, getWebhookDeliveries, getWebhooks, removeMember, revokeApiKey, testWebhook, updateMember } from '../../api/enterprise'

const PanelTitle=defineComponent({props:['title','text'],setup(p,{slots}){return()=>h('div',{class:'panel-head'},[h('div',[h('h2',p.title),h('p',p.text)]),slots.default?.()])}})
const ItemList=defineComponent({props:['items','empty'],setup(p,{slots}){return()=>h('div',{class:'rows'},p.items?.length?p.items.map(item=>h('div',{class:'item'},slots.default?.({item}))):h('p',{class:'empty'},p.empty))}})
const data=reactive({}),organization=reactive({members:[]}),operations=reactive({services:{},task_counts:{}}),audits=ref([]),knowledge=ref([]),schedules=ref([]),apiKeys=ref([]),webhooks=ref([]),deliveries=ref([]),backups=ref([]),workflows=ref([]),documents=ref([]),organizations=ref([]),activeOrganization=ref(''),tab=ref('team'),dialog=ref(''),loading=ref(true),saving=ref(false),backing=ref(false),secret=ref(''),form=reactive({})
const tabs=[['team','团队权限'],['audit','审计日志'],['knowledge','知识库'],['automation','计划任务'],['integration','开放集成'],['operations','运维备份'],['billing','套餐用量']].map(([key,name])=>({key,name})),roles=[['viewer','访客'],['member','成员'],['reviewer','复核员'],['admin','管理员'],['owner','所有者']].map(([value,name])=>({value,name})),roleNames={viewer:'访客',member:'成员',reviewer:'复核员',admin:'管理员',owner:'所有者'},modeNames={keyword:'关键词检索',vector:'向量检索',hybrid:'混合检索'},serviceNames={api:'接口服务',database:'数据库',redis:'缓存服务',queue:'任务进程',model:'大模型'}
const deliveryNames={queued:'排队中',delivering:'投递中',delivered:'已送达',failed:'失败',cancelled:'已取消'}
const plans=[{key:'starter',name:'基础版',price:'本地免费',lines:['3 名成员','500 份文档','200 次/月','2 GB 空间']},{key:'team',name:'团队版',price:'手动授权',lines:['20 名成员','10,000 份文档','5,000 次/月','50 GB 空间']},{key:'enterprise',name:'企业版',price:'合同授权',lines:['企业成员规模','高额度工作流','TB 级空间','专属集成支持']}]
const bytes=v=>{if(!v)return'0 B';const u=['B','KB','MB','GB','TB'],i=Math.min(Math.floor(Math.log(v)/Math.log(1024)),4);return`${(v/1024**i).toFixed(i?1:0)} ${u[i]}`},date=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—',short=v=>v?v.slice(0,8):'—',detail=v=>Object.keys(v||{}).length?JSON.stringify(v):'—'
const metrics=computed(()=>{const m=data.metrics||{};return[['团队成员',m.members||0,'人'],['文档资产',m.documents||0,'文'],['工作流运行',m.workflow_runs||0,'流'],['待复核',m.pending_reviews||0,'审'],['占用空间',bytes(m.storage_bytes||0),'存']].map(([name,value,icon])=>({name,value,icon}))}),usage=computed(()=>{const m=data.metrics||{},l=data.subscription?.limits||{},u=data.subscription?.usage||{};return[['成员',m.members||0,l.members||0],['文档',m.documents||0,l.documents||0],['本月运行',u.monthly_runs||0,l.monthly_runs||0],['存储空间',m.storage_bytes||0,l.storage_bytes||0]].map(([name,raw,limit])=>({name,used:name==='存储空间'?bytes(raw):raw,limit:name==='存储空间'?bytes(limit):limit,percent:Math.min(100,Math.round(raw/(limit||1)*100))}))}),dialogTitle=computed(()=>({member:'添加成员',knowledge:'新建知识库',schedule:'新建计划任务',key:'创建 API 密钥',webhook:'添加 Webhook'}[dialog.value]))
const core=async()=>{loading.value=true;try{const[d,o,w,os,docs]=await Promise.all([getEnterpriseDashboard(),getOrganization(),getWorkflows(),getOrganizations(),getDocuments({limit:100})]);Object.assign(data,d);Object.assign(organization,o);workflows.value=w.items;documents.value=docs.items;organizations.value=os.items;activeOrganization.value=d.organization.id}finally{loading.value=false}},switchOrganization=async()=>{await activateOrganization(activeOrganization.value);await core()},loadAudit=async()=>audits.value=(await getAuditLogs()).items,loadKnowledge=async()=>knowledge.value=(await getKnowledge()).items,loadSchedules=async()=>schedules.value=(await getSchedules()).items,loadIntegrations=async()=>{const[k,w,d]=await Promise.all([getApiKeys(),getWebhooks(),getWebhookDeliveries()]);apiKeys.value=k.items;webhooks.value=w.items;deliveries.value=d.items},loadOperations=async()=>{const[o,b]=await Promise.all([getOperations(),getBackups()]);Object.assign(operations,o);backups.value=b.items}
const selectTab=async value=>{tab.value=value;try{if(value==='audit')await loadAudit();if(value==='knowledge')await loadKnowledge();if(value==='automation')await loadSchedules();if(value==='integration')await loadIntegrations();if(value==='operations')await loadOperations()}catch(e){alert(e.message)}},open=type=>{dialog.value=type;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,type==='member'?{email:'',role:'member'}:type==='knowledge'?{name:'',description:'',retrieval_mode:'hybrid'}:type==='schedule'?{name:'',workflow_id:'',document_id:'',cron_expression:'0 9 * * 1-5',timezone:'Asia/Shanghai',retry_limit:2}:type==='key'?{name:'',scope:'workspace:read'}:{name:'',url:'',events:'task.succeeded,task.failed,review.approved'})}
const submit=async()=>{saving.value=true;try{if(dialog.value==='member'){await addMember(form);Object.assign(organization,await getOrganization())}else if(dialog.value==='knowledge'){await createKnowledge(form);await loadKnowledge()}else if(dialog.value==='schedule'){await createSchedule(form);await loadSchedules()}else if(dialog.value==='key'){const r=await createApiKey({name:form.name,scopes:[form.scope],expires_in_days:90});secret.value=r.key;await loadIntegrations()}else{const r=await createWebhook({name:form.name,url:form.url,events:form.events.split(',').map(i=>i.trim()).filter(Boolean)});secret.value=r.signing_secret;await loadIntegrations()}dialog.value='';await core()}catch(e){alert(e.message)}finally{saving.value=false}}
const saveRole=async m=>{try{await updateMember(m.id,{role:m.role})}catch(e){alert(e.message);Object.assign(organization,await getOrganization())}},dropMember=async m=>{if(confirm(`确定移除 ${m.username} 吗？`)){await removeMember(m.id);Object.assign(organization,await getOrganization());await core()}},dropSchedule=async i=>{if(confirm(`确定删除 ${i.name} 吗？`)){await deleteSchedule(i.id);await loadSchedules()}},dropKey=async i=>{if(confirm(`确定撤销 ${i.name} 吗？`)){await revokeApiKey(i.id);await loadIntegrations()}},dropWebhook=async i=>{if(confirm(`确定删除 ${i.name} 吗？`)){await deleteWebhook(i.id);await loadIntegrations()}},tryWebhook=async i=>{const r=await testWebhook(i.id);await loadIntegrations();alert(r.queued?`测试事件已进入投递队列：${r.delivery_ids[0]}`:'当前端点未订阅可测试事件')},setPlan=async p=>{if(confirm('确认切换本地套餐配置吗？')){await changePlan(p);await core()}},backup=async()=>{backing.value=true;try{await createBackup();await loadOperations()}finally{backing.value=false}},copy=()=>navigator.clipboard.writeText(secret.value),serviceState=s=>s.status==='healthy'?`正常${s.latency_ms!==undefined?` · ${s.latency_ms} ms`:s.workers!==undefined?` · ${s.workers} 个进程`:''}`:s.status==='configured'?`已配置 · ${s.provider}`:s.status==='unconfigured'?'未配置':s.status,actionName=a=>({'document.upload':'上传文档','document.update':'更新文档','document.delete':'删除文档','workflow.create':'创建工作流','workflow.update':'更新工作流','workflow.run':'运行工作流','review.approve':'通过复核','member.add':'添加成员','api_key.create':'创建 API 密钥','backup.create':'创建备份'}[a]||a)
onMounted(core)
</script>

<style scoped>
